const $=s=>document.querySelector(s), form=$('#lesson-form'), filters=$('#filters');
let config, students=[],editing=null,offset=0,weekStart,busy=false;
const states={scheduled:'Запланировано',completed:'Проведено',cancelled:'Отменено'};
function plus(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function localInput(value){const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:config.timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value));return parts.replace(' ','T')}
function text(tag,value){const e=document.createElement(tag);e.textContent=value;return e}
function money(value){return (value/100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₽'}
async function api(path='',method='GET',data){const response=await fetch('/api/lessons'+path,{method,cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json','X-Requested-With':'KrugPi'},...(data?{body:JSON.stringify(data)}:{})});const result=await response.json();if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:response.status===401?'Войдите в личный кабинет.':'Проверьте заполнение полей.');return result}
function scopeFor(row){if(!row.series_id)return 'one';const choice=prompt('Область изменения: 1 — только этот урок; 2 — этот и следующие; 3 — все будущие уроки серии','1');return {'1':'one','2':'following','3':'series'}[choice]}
function card(row,actions=true){const e=text('article','');e.className='lesson-card '+row.status;e.append(text('strong',new Date(row.starts_at).toLocaleString('ru-RU',{timeZone:config.timezone,dateStyle:'short',timeStyle:'short'})));if(config.role==='admin')e.append(text('h3',row.student_name));e.append(text('p',states[row.status]+' · '+row.duration_minutes+' мин · '+money(row.price_kopecks)));if(row.topic)e.append(text('p',row.topic));if(row.series_id)e.append(text('small','Повторяющееся занятие'));if(row.meeting_url&&row.status==='scheduled'){const a=text('a','Открыть онлайн-урок →');a.href=row.meeting_url;a.target='_blank';a.rel='noopener noreferrer';e.append(text('p',''),a)}if(config.role==='admin'&&actions&&row.status!=='completed'){const controls=text('div','');controls.className='lesson-actions';for(const [label,handler] of [['Изменить',()=>openEditor(row)],[row.status==='cancelled'?'Возобновить':'Отменить',()=>changeStatus(row,row.status==='cancelled'?'scheduled':'cancelled')],['Проведено',()=>changeStatus(row,'completed')],['Удалить',()=>remove(row)]]){const b=text('button',label);b.type='button';b.onclick=handler;controls.append(b)}e.append(controls)}return e}
function defaults(){const student=students.find(s=>s.id===Number(form.elements.student_id.value));if(student){form.elements.duration_minutes.value=student.default_duration_minutes;form.elements.price.value=(student.default_price_kopecks/100).toFixed(2)}}
function openEditor(row=null){editing=row;form.reset();form.querySelector('[type=submit]').disabled=false;$('#form-status').textContent='';$('#editor').hidden=false;$('#editor-title').textContent=row?'Изменить занятие':'Новое занятие';$('#recurrence').hidden=!!row;$('#edit-scope').hidden=!row?.series_id;form.elements.scope.value='one';if(row){if(!students.some(s=>s.id===row.student_id)){ form.querySelector('[type=submit]').disabled=true;$('#form-status').textContent='Ученик архивирован. Для переноса сначала восстановите его в кабинете администратора.';return;}for(const field of ['student_id','duration_minutes','topic','meeting_url'])form.elements[field].value=row[field];form.elements.starts_at.value=localInput(row.starts_at);form.elements.price.value=(row.price_kopecks/100).toFixed(2)}else{defaults();form.elements.starts_at.value=config.today+'T12:00'}$('#editor').scrollIntoView({block:'start'});form.elements.student_id.focus()}
async function mutate(action){if(busy)return;busy=true;try{await action();$('#status').textContent='Изменения сохранены';await refresh()}catch(e){$('#status').textContent=e.message}finally{busy=false}}
async function changeStatus(row,status){const scope=status==='completed'?'one':scopeFor(row);if(!scope||!confirm('Изменить статус: '+states[status]+'?'))return;await mutate(()=>api('/'+row.id+'/status','PATCH',{status,scope}))}
async function remove(row){const scope=scopeFor(row);if(!scope||!confirm('Удалить выбранные будущие занятия? Для сохранения истории используйте отмену.'))return;await mutate(()=>api('/'+row.id+'?scope='+scope,'DELETE'))}
form.elements.student_id.onchange=defaults;
form.onsubmit=async event=>{event.preventDefault();const price=form.elements.price.value.replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(price)){ $('#form-status').textContent='Введите цену с точностью до копеек';return}const [rub,kop='']=price.split('.');const data={student_id:Number(form.elements.student_id.value),starts_at:form.elements.starts_at.value,timezone:config.timezone,duration_minutes:Number(form.elements.duration_minutes.value),price_kopecks:Number(rub)*100+Number(kop.padEnd(2,'0')),topic:form.elements.topic.value,meeting_url:form.elements.meeting_url.value};if(editing)data.scope=form.elements.scope.value;else{data.weekdays=[...form.querySelectorAll('[name=weekday]:checked')].map(e=>Number(e.value));data.recurrence_end=form.elements.recurrence_end.value||null}const button=form.querySelector('[type=submit]');button.disabled=true;try{const result=await api(editing?'/'+editing.id:'',editing?'PUT':'POST',data);$('#editor').hidden=true;$('#status').textContent=editing?'Занятия обновлены':'Создано занятий: '+result.count;await refresh()}catch(e){$('#form-status').textContent=e.message}finally{button.disabled=false}};
async function calendar(){const end=plus(weekStart,7);$('#week-label').textContent=weekStart+' — '+plus(weekStart,6);const rows=[];let start=0,total=0;do{const data=await api('?'+new URLSearchParams({from_date:weekStart,to_date:end,limit:100,offset:start}));rows.push(...data.items);total=data.total;start+=100}while(start<total);$('#calendar').replaceChildren();if(config.role==='student'){if(!rows.length)$('#calendar').append(text('p','На этой неделе занятий нет.'));for(const row of rows)$('#calendar').append(card(row,false));return}for(let i=0;i<7;i++){const day=plus(weekStart,i),column=text('section','');column.className='calendar-day';column.append(text('h3',new Date(day+'T12:00:00Z').toLocaleDateString('ru-RU',{timeZone:'UTC',weekday:'short',day:'numeric',month:'short'})));for(const row of rows.filter(r=>localInput(r.starts_at).slice(0,10)===day))column.append(card(row,false));$('#calendar').append(column)}}
async function list(){const params=new URLSearchParams({limit:20,offset});if(filters.elements.from_date.value)params.set('from_date',filters.elements.from_date.value);if(filters.elements.to_date.value)params.set('to_date',plus(filters.elements.to_date.value,1));if(filters.elements.student_id.value)params.set('student_id',filters.elements.student_id.value);const data=await api('?'+params);$('#lessons-list').replaceChildren(...data.items.map(r=>card(r)));$('#list-count').textContent='Всего: '+data.total;if(!data.items.length)$('#lessons-list').append(text('p','В этом периоде занятий нет.'));$('#previous-page').disabled=offset===0;$('#next-page').disabled=offset+20>=data.total}
async function refresh(){await calendar();await list()}
$('#add').onclick=()=>openEditor();$('#cancel').onclick=()=>{$('#editor').hidden=true};$('#refresh').onclick=()=>refresh().catch(e=>$('#status').textContent=e.message);
filters.onsubmit=event=>{event.preventDefault();offset=0;list().catch(e=>$('#status').textContent=e.message)};
for(const [selector,delta] of [['#previous-week',-7],['#next-week',7]])$(selector).onclick=()=>{weekStart=plus(weekStart,delta);calendar().catch(e=>$('#status').textContent=e.message)};
function currentWeek(){weekStart=plus(config.today,-((new Date(config.today+'T12:00:00Z').getUTCDay()+6)%7))}
$('#this-week').onclick=()=>{currentWeek();calendar().catch(e=>$('#status').textContent=e.message)};
$('#previous-page').onclick=()=>{offset=Math.max(0,offset-20);list().catch(e=>$('#status').textContent=e.message)};$('#next-page').onclick=()=>{offset+=20;list().catch(e=>$('#status').textContent=e.message)};
(async()=>{try{config=await api('/settings');$('#zone').textContent='Все даты и время: '+config.timezone;currentWeek();if(config.role==='admin'){ $('#back').href='admin.html';$('#add').hidden=false;$('#student-filter').hidden=false;let start=0,total;do{const r=await fetch('/api/admin/students?limit=100&offset='+start);if(!r.ok)throw Error('Не удалось загрузить учеников');const d=await r.json();students.push(...d.items.filter(s=>s.is_active));total=d.total;start+=100}while(start<total);for(const student of students){for(const select of [form.elements.student_id,filters.elements.student_id]){const option=text('option',student.name+' ('+student.username+')');option.value=student.id;select.append(option)}}}else $('#calendar').style.display='block';await refresh();$('#content').hidden=false;$('#status').textContent=''}catch(e){$('#status').textContent=e.message}})();
